import{_ as l,o,c as a,ag as e}from"./chunks/framework.D7Pdja0E.js";const p=JSON.parse('{"title":"사용자 관리","description":"","frontmatter":{},"headers":[],"relativePath":"04-org-admin-guide/users.md","filePath":"04-org-admin-guide/users.md","lastUpdated":1776993543000}'),d={name:"04-org-admin-guide/users.md"};function i(r,t,s,n,u,h){return o(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="사용자-관리" tabindex="-1">사용자 관리 <a class="header-anchor" href="#사용자-관리" aria-label="Permalink to &quot;사용자 관리&quot;">​</a></h1><p>기관 관리자는 조직 내 모든 사용자 계정을 관리합니다.</p><h2 id="사용자-목록" tabindex="-1">사용자 목록 <a class="header-anchor" href="#사용자-목록" aria-label="Permalink to &quot;사용자 목록&quot;">​</a></h2><p>관리 &gt; <strong>사용자 관리</strong> 메뉴에서 전체 사용자 목록을 확인합니다.</p><p>각 사용자의 다음 정보가 표시됩니다:</p><ul><li>이름</li><li>이메일</li><li>부서</li><li>역할 (시스템 관리자 / 기관 관리자 / 부서 관리자 / 일반 사용자)</li><li>상태 (활성 / 비활성 / 대기)</li></ul><h2 id="사용자-초대" tabindex="-1">사용자 초대 <a class="header-anchor" href="#사용자-초대" aria-label="Permalink to &quot;사용자 초대&quot;">​</a></h2><p>사용자를 조직에 초대하는 방법은 두 가지입니다.</p><h3 id="이메일-초대" tabindex="-1">이메일 초대 <a class="header-anchor" href="#이메일-초대" aria-label="Permalink to &quot;이메일 초대&quot;">​</a></h3><ol><li>관리 &gt; <strong>초대 관리</strong> 메뉴에서 <strong>&quot;초대 보내기&quot;</strong> 버튼을 클릭합니다.</li><li>다음 정보를 입력합니다: <ul><li>이메일</li><li>역할</li><li>소속 부서 (선택)</li></ul></li><li><strong>&quot;초대&quot;</strong> 버튼을 클릭하면 초대 이메일이 발송됩니다.</li><li>부서를 지정한 경우, 가입 완료 시 해당 부서에 자동 배정됩니다.</li></ol><h3 id="초대-코드" tabindex="-1">초대 코드 <a class="header-anchor" href="#초대-코드" aria-label="Permalink to &quot;초대 코드&quot;">​</a></h3><p>다수의 사용자를 한번에 초대할 때 유용합니다.</p><ol><li>관리 &gt; <strong>초대 관리</strong> 메뉴의 <strong>초대 코드</strong> 탭을 클릭합니다.</li><li><strong>&quot;코드 생성&quot;</strong> 버튼을 클릭합니다.</li><li>다음 정보를 설정합니다: <ul><li>역할</li><li>소속 부서 (선택)</li><li>사용 횟수 제한</li><li>만료일</li></ul></li><li>생성된 코드를 사용자에게 전달합니다.</li><li>부서를 지정한 경우, 코드로 가입한 사용자는 해당 부서에 자동 배정됩니다.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>초대 시 부서를 지정하면 신규 사용자가 가입 즉시 올바른 부서에 배정되므로, 별도의 부서 배정 작업이 필요 없습니다.</p></div><h2 id="사용자-수정" tabindex="-1">사용자 수정 <a class="header-anchor" href="#사용자-수정" aria-label="Permalink to &quot;사용자 수정&quot;">​</a></h2><ol><li>사용자 목록에서 대상 사용자를 클릭합니다.</li><li>이름, 부서, 역할 등을 수정합니다.</li><li>변경 사항을 저장합니다.</li></ol><h2 id="사용자-사용중지-suspend" tabindex="-1">사용자 사용중지 (suspend) <a class="header-anchor" href="#사용자-사용중지-suspend" aria-label="Permalink to &quot;사용자 사용중지 (suspend)&quot;">​</a></h2><p>퇴사자·장기 부재자 등의 계정을 관리자가 즉시 사용중지할 수 있습니다.</p><ol><li><strong>관리자 → 사용자</strong> 페이지에서 대상 사용자 행의 <strong>&quot;사용중지&quot;</strong> 버튼을 클릭합니다.</li><li>확인 다이얼로그에서 진행하면: <ul><li><code>status = &#39;suspended&#39;</code> 로 변경</li><li>해당 사용자의 <strong>모든 기기 세션이 즉시 폐기</strong> (refresh token 포함)</li><li>이후 로그인 시도 시 <em>&quot;사용 중지된 계정입니다. 관리자에게 문의하세요.&quot;</em> 메시지 표시</li></ul></li><li>복구가 필요할 때 같은 자리에 나타나는 <strong>&quot;복구&quot;</strong> 버튼으로 <code>status = &#39;active&#39;</code> 로 되돌릴 수 있습니다.</li></ol><p><strong>제한</strong></p><ul><li>자기 자신은 사용중지할 수 없습니다 (계정 락아웃 방지).</li><li>탈퇴(<code>withdrawn</code>) 상태 사용자는 사용중지/복구 대상이 아닙니다.</li><li>데이터(메시지, 태스크 등)는 유지됩니다.</li></ul><h2 id="사용자-본인-탈퇴" tabindex="-1">사용자 본인 탈퇴 <a class="header-anchor" href="#사용자-본인-탈퇴" aria-label="Permalink to &quot;사용자 본인 탈퇴&quot;">​</a></h2><p>사용자 스스로 <strong>내 프로필 → 위험 영역 → 계정 탈퇴</strong>에서 탈퇴할 수 있습니다.</p><ul><li>현재 비밀번호 재확인 + &quot;탈퇴&quot; 문구 입력 2단계 확인</li><li>탈퇴 시 <code>status = &#39;withdrawn&#39;</code>, 모든 세션 폐기</li><li>작성한 메시지·태스크 이력은 보존되며 &quot;탈퇴한 사용자&quot;로 표시됩니다</li><li><strong>동일 이메일로 재가입 시 기존 계정(UUID·이력)이 자동 복구</strong>됩니다</li></ul><blockquote><p>SSO 전용 계정(비밀번호 미설정)은 본인 탈퇴 경로로 탈퇴할 수 없으며, 관리자가 수동으로 처리해야 합니다.</p></blockquote><h2 id="상태-요약" tabindex="-1">상태 요약 <a class="header-anchor" href="#상태-요약" aria-label="Permalink to &quot;상태 요약&quot;">​</a></h2><table tabindex="0"><thead><tr><th>상태</th><th>로그인</th><th>설명</th></tr></thead><tbody><tr><td><code>active</code></td><td>✅</td><td>정상 사용</td></tr><tr><td><code>suspended</code></td><td>❌</td><td>관리자에 의해 사용중지. 복구 가능</td></tr><tr><td><code>withdrawn</code></td><td>❌</td><td>본인 탈퇴. 동일 이메일 재가입 시 복구</td></tr><tr><td><code>pending</code></td><td>❌</td><td>승인 대기</td></tr><tr><td><code>inactive</code></td><td>❌</td><td>레거시 (비활성)</td></tr></tbody></table><blockquote><p><strong>사용자 삭제는 지원하지 않습니다.</strong> 데이터 무결성(메시지 작성자 등 NOT NULL FK)을 위해 soft delete(suspend/withdraw)만 제공합니다.</p></blockquote><h2 id="역할-체계" tabindex="-1">역할 체계 <a class="header-anchor" href="#역할-체계" aria-label="Permalink to &quot;역할 체계&quot;">​</a></h2><table tabindex="0"><thead><tr><th>역할</th><th>범위</th><th>주요 권한</th></tr></thead><tbody><tr><td>시스템 관리자</td><td>전체 시스템</td><td>서버 설정, 조직 생성</td></tr><tr><td>기관 관리자</td><td>조직 전체</td><td>사용자/부서/보안 관리</td></tr><tr><td>부서 관리자</td><td>소속 부서</td><td>구성원/채널/프로젝트 관리</td></tr><tr><td>일반 사용자</td><td>참여 채널/프로젝트</td><td>메시지, 태스크</td></tr></tbody></table>',30)])])}const g=l(d,[["render",i]]);export{p as __pageData,g as default};
